-- Schema exported from the verified candidate.
CREATE TABLE _columns(table_name VARCHAR, column_name VARCHAR, data_type VARCHAR, source_file VARCHAR, example_value VARCHAR, join_hint VARCHAR, null_pct DOUBLE);

CREATE TABLE _metadata(table_name VARCHAR, description VARCHAR, row_count BIGINT, column_count INTEGER, source_url VARCHAR, license VARCHAR, built_at TIMESTAMP, source_file VARCHAR, source_sha256 VARCHAR, source_version VARCHAR, source_dataset_id VARCHAR);

CREATE TABLE enrollment(state_abbreviation VARCHAR, state_name VARCHAR, reporting_period VARCHAR, state_expanded_medicaid VARCHAR, preliminary_updated VARCHAR, final_report VARCHAR, new_applications_submitted_to_medicaid_and_chip_agencies BIGINT, new_applications_submitted_to_medicaid_and_chip_agencies_footnotes VARCHAR, applications_for_financial_assistance_submitted_to_the_state_based_marketplace BIGINT, applications_for_financial_assistance_submitted_to_the_state_based_marketplace_footnotes VARCHAR, total_applications_for_financial_assistance_submitted_at_state_level BIGINT, total_applications_for_financial_assistance_submitted_at_state_level_footnotes VARCHAR, individuals_determined_eligible_for_medicaid_at_application BIGINT, individuals_determined_eligible_for_medicaid_at_application_footnotes VARCHAR, individuals_determined_eligible_for_chip_at_application BIGINT, individuals_determined_eligible_for_chip_at_application_footnotes VARCHAR, total_medicaid_and_chip_determinations BIGINT, total_medicaid_and_chip_determinations_footnotes VARCHAR, medicaid_and_chip_child_enrollment BIGINT, medicaid_and_chip_child_enrollment_footnotes VARCHAR, total_medicaid_and_chip_enrollment BIGINT, total_medicaid_and_chip_enrollment_footnotes VARCHAR, total_medicaid_enrollment BIGINT, total_medicaid_enrollment_footnotes VARCHAR, total_chip_enrollment BIGINT, total_chip_enrollment_footnotes VARCHAR, total_medicaid_adult_enrollment BIGINT, total_medicaid_adult_enrollment_footnotes VARCHAR, total_medicaid_and_chip_determinations_processed_in_less_than_24_hours BIGINT, total_medicaid_and_chip_determinations_processed_in_less_than_24_hours_footnotes VARCHAR, total_medicaid_and_chip_determinations_processed_between_24_hours_and_7_days BIGINT, total_medicaid_and_chip_determinations_processed_between_24_hours_and_7_days_footnotes VARCHAR, total_medicaid_and_chip_determinations_processed_between_8_days_and_30_days BIGINT, total_medicaid_and_chip_determinations_processed_between_8_days_and_30_days_footnotes VARCHAR, total_medicaid_and_chip_determinations_processed_between_31_days_and_45_days BIGINT, total_medicaid_and_chip_determinations_processed_between_31_days_and_45_days_footnotes VARCHAR, total_medicaid_and_chip_determinations_processed_in_more_than_45_days BIGINT, total_medicaid_and_chip_determinations_processed_in_more_than_45_days_footnotes VARCHAR, total_call_center_volume BIGINT, total_call_center_volume_footnotes VARCHAR, average_call_center_wait_time BIGINT, average_call_center_wait_time_footnotes VARCHAR, average_call_center_abandonment_rate DECIMAL(12,6), average_call_center_abandonment_rate_footnotes VARCHAR, source_row_number BIGINT NOT NULL UNIQUE, reporting_month DATE, is_baseline BOOLEAN NOT NULL, PRIMARY KEY(state_abbreviation, reporting_period, preliminary_updated));

CREATE TABLE field_definitions(ordinal INTEGER PRIMARY KEY, column_name VARCHAR UNIQUE, source_header VARCHAR, source_type VARCHAR, duckdb_type VARCHAR, description VARCHAR);

CREATE VIEW baseline_enrollment AS SELECT * FROM enrollment WHERE is_baseline;

CREATE VIEW monthly_preliminary AS SELECT * FROM enrollment WHERE ((NOT is_baseline) AND (preliminary_updated = 'P'));

CREATE VIEW monthly_updated AS SELECT * FROM enrollment WHERE ((NOT is_baseline) AND (preliminary_updated = 'U'));
